p=argparse.ArgumentParser();p.add_argument('arm',choices=['base','depth','serializer','stack']);p.add_argument('name');p.add_argument('--workload',required=True,choices=['reference6']);p.add_argument('--warmups',type=int,default=60);p.add_argument('--iterations',type=int,default=20);p.add_argument('--validate',action='store_true');p.add_argument('--browser',action='store_true');a=p.parse_args()
r=pathlib.Path(__file__).resolve().parents[3];os.chdir(r);d=pathlib.Path(__file__).resolve().parent; common=d.parent/'depth-workbench'
out=d/'runs'/a.name;assert not out.exists(),'Refuse replacing prior run';out.mkdir(parents=True)
lock=open(r/'experiments/overlay/native-benchmark.lock','w');fcntl.flock(lock,fcntl.LOCK_EX)
groups,width={'small6':(10,6),'reference6':(100,6),'wide30':(100,30),'large6':(250,6)}[a.workload];expectedRows=groups*1000
fixture=d.parent/'range-workbench/fixtures'/('g'+str(groups));appdata=out/'appdata';shutil.copytree(fixture,appdata)
