manifest={'arm':a.arm,'source':json.loads((d/'source-identities.json').read_text())[a.arm],'command':cmd,'workload':a.workload,'groups':groups,'width':width,'expectedRows':expectedRows,'warmups':a.warmups,'iterations':a.iterations,'validate':a.validate,'scope':'Actual Server/Workbench to Node NDJSON, excludes browser rendering unless explicit browser mode','start':time.time()};(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
